,"<p src=\"https://example.com\">Sayt</p>","<link>Sayt</link>"],"cognitive":"qollash","construct":"S5.WEB.04","difficulty":3},{"exp":"<br> matnda qator uzilishini hosil qiladi.","ref":"reserve-2026:T060-R2-WEB-Q11","stem":"Paragraf ichida yangi qatorga majburiy o‘tish kerak. Qaysi teg mos?","correct":0,"options":["<br>","<hr> faqat jadval uchun","<img>","<title>"],"cognitive":"qollash","construct":"S5.WEB.04","difficulty":3},{"exp":"<tr> jadval qatorini, <td>/<th> esa uning kataklarini belgilaydi.","ref":"reserve-2026:T060-R2-WEB-Q12","stem":"HTML jadvalida yangi qator yaratish uchun qaysi teg ishlatiladi?","correct":0,"options":["<tr>","<td>","<th>","<input>"],"cognitive":"qollash","construct":"S5.WEB.05","difficulty":3},{"exp":"Bir qatorli matn kiritish uchun input type=text ishlatiladi.","ref":"reserve-2026:T060-R2-WEB-Q13","stem":"Forma ichida foydalanuvchi ism kiritishi uchun bir qatorli matn maydoni kerak. Qaysi element mos?","correct":0,"options":["<input type=\"text\">","<img type=\"text\">","<table type=\"text\">","<a type=\"text\">"],"cognitive":"qollash","construct":"S5.WEB.05","difficulty":3},{"exp":"Bir guruhdan bitta variant tanlash uchun radio inputlar mos.","ref":"reserve-2026:T060-R2-WEB-Q14","stem":"Foydalanuvchi faqat bitta variantni tanlashi kerak bo‘lgan guruh uchun qaysi forma elementi mos?","correct":0,"options":["Radio tugmalar","Bir nechta mustaqil checkbox","Rasm tegi","Jadval qatori"],"cognitive":"qollash","construct":"S5.WEB.05","difficulty":3},{"exp":"CSSda selektor p va color xossasi ishlatiladi.","ref":"reserve-2026:T060-R2-WEB-Q15","stem":"Barcha `<p>` elementlari matnini ko‘k qilish uchun qaysi CSS qoida to‘g‘ri?","correct":0,"options":["p { color: blue; }","p = color(blue)","<p color=blue> CSS","color:p:blue"],"cognitive":"qollash","construct":"S5.WEB.06","difficulty":3},{"exp":"ID selektori # belgisi bilan yoziladi.","ref":"reserve-2026:T060-R2-WEB-Q16","stem":"Faqat `id=\"menu\"` bo‘lgan elementga CSS qo‘llash uchun qaysi selektor kerak?","correct":0,"options":["#menu",".menu","menu*","@menu"],"cognitive":"qollash","construct":"S5.WEB.06","difficulty":3},{"exp":"Class selektori nuqta bilan boshlanadi.","ref":"reserve-2026:T060-R2-WEB-Q17","stem":"`class=\"warning\"` berilgan bir nechta elementni tanlash uchun qaysi CSS selektor mos?","correct":0,"options":[".warning","#warning","warning#","@warning"],"cognitive":"qollash","construct":"S5.WEB.06","difficulty":3},{"exp":"background-color element fon rangini belgilaydi.","ref":"reserve-2026:T060-R2-WEB-Q18","stem":"Element fonini sariq qilish uchun qaysi CSS xossa ishlatiladi?","correct":0,"options":["background-color","font-family","text-align","border-collapse"],"cognitive":"qollash","construct":"S5.WEB.06","difficulty":3},{"exp":"width xossasi element kengligini belgilaydi.","ref":"reserve-2026:T060-R2-WEB-Q19","stem":"Rasmning CSS orqali kengligini 200 piksel qilish uchun qaysi qoida mos?","correct":0,"options":["img { width: 200px; }","img { font-size: 200px; }","img { color: 200px; }","img { href: 200px; }"],"cognitive":"qollash","construct":"S5.WEB.06","difficulty":3}]'::jsonb)
 loop
  if exists(select 1 from public.questions where source_reference=item->>'ref') then
   continue;
  end if;

  select c.id,c.subject_id,c.group_code
    into v_construct,v_subject,v_group
    from public.constructs c
   where c.code=item->>'construct'
     and c.is_active;

  if v_construct is null then
   raise exception 'TASK-060 R2 construct not found: %',item->>'construct';
  end if;

  select l.id into v_lesson
    from public.lesson_constructs lc
    join public.lessons l on l.id=lc.lesson_id
   where lc.construct_id=v_construct
     and l.status='published'::public.content_status
   order by l.order_idx,l.id
   limit 1;

  if v_lesson is null then
   raise exception 'TASK-060 R2 source lesson not found: %',item->>'construct';
  end if;

  v_question:=gen_random_uuid();
  insert into public.questions(
    id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,
    assets,is_generated,status,author_id,source_reference,source_lesson_id
  ) values (
    v_question,v_subject,v_construct,v_group,
    'Y1'::public.question_format,
    (item->>'cognitive')::public.cognitive_level,
    (item->>'difficulty')::int,
    item->>'stem',
    '[]'::jsonb,
    false,
    'published'::public.content_status,
    null,
    item->>'ref',
    v_lesson
  );

  v_correct:=(item->>'correct')::int;
  for v_i in 0..3 loop
   v_option:=gen_random_uuid();
   insert into public.question_options(id,question_id,content_md,order_idx)
   values(v_option,v_question,item->'options'->>v_i,v_i);

   if v_i=v_correct then
    insert into public.question_keys(question_id,payload,explanation_md)
    values(v_question,jsonb_build_object('correct_option_id',v_option),item->>'exp');
   end if;
  end loop;
 end loop;
end
$$;

